{"command": "cat > /tmp/work/parse.py <<'PYEOF'
import re,sys
rows=sys.stdin.read().split('\n')
if rows and rows[-1]=='': rows.pop()
colors={'\x1b[39m':'d'}
out=[]
for r in rows:
    cells=[]  # (char, style)
    cur='\x1b[0m'
    i=0
    s=r
    while i<len(s):
        m=re.match(r'\x1b\[[0-9;]*m', s[i:])
        if m:
            cur=m.group(0); i+=m.end(); continue
        cells.append((s[i],cur)); i+=1
    out.append(cells)
for ri,cells in enumerate(out):
    line=''.join(c for c,_ in cells)
    print(f'{ri:2d}|{line}')
