use std::io::Write;
use std::sync::{Arc, Mutex};
#[derive(Clone)]
struct W(Arc<Mutex<Vec<u8>>>);
impl Write for W {
    fn write(&mut self, b: &[u8]) -> std::io::Result<usize> { self.0.lock().unwrap().extend_from_slice(b); Ok(b.len()) }
    fn flush(&mut self) -> std::io::Result<()> { Ok(()) }
}
use ratatui::{backend::CrosstermBackend, Terminal};
use ratatui::style::{Style, Color, Stylize};
fn main() {
    let w = W(Arc::new(Mutex::new(Vec::new())));
    let mut term = Terminal::new(CrosstermBackend::new(w.clone())).unwrap();
    term.draw(|f| {
        Paragraph2::new("abc", Style::new().fg(Color::Indexed(13))).render(f.area(), f.buffer_mut());
    }).unwrap();
    term.draw(|f| {
        Paragraph2::new("abc", Style::new().fg(Color::Rgb(10,20,30)).bg(Color::Rgb(1,2,3))).render(f.area(), f.buffer_mut());
    }).unwrap();
    term.draw(|f| {
        Paragraph2::new("abc", Style::new().bold().fg(Color::Black).bg(Color::Green)).render(f.area(), f.buffer_mut());
    }).unwrap();
    let d = w.0.lock().unwrap().clone();
    println!("{:?}", String::from_utf8_lossy(&d));
}
struct Paragraph2<'a> { t: &'a str, s: Style }
impl<'a> Paragraph2<'a> { fn new(t: &'a str, s: Style) -> Self { Self { t, s } } }
impl ratatui::widgets::Widget for Paragraph2<'_> {
    fn render(self, area: ratatui::layout::Rect, buf: &mut ratatui::buffer::Buffer) {
        use ratatui::widgets::StatefulWidget as _;
        // simple: set style over area and put text
        buf.set_style(area, self.s);
        let mut s = String::new();
        s.push_str(self.t);
        for (x, c) in s.chars().enumerate() {
            if let Some(cell) = buf.cell_mut((area.x + x as u16, area.y)) { cell.set_symbol(&c.to_string()); }
        }
    }
}
