import re, sys

def render(data, cols, rows):
    grid=[[(' ', '') for _ in range(cols)] for _ in range(rows)]
    r=c=0; fg=None; bg=None; mod=set()
    i=0
    while i < len(data):
        ch=data[i]
        if ch=='\x1b':
            m=re.match(r'\x1b\[(\d*);?(\d*)H', data[i:])
            if m:
                r=int(m.group(1) or 1)-1; c=int(m.group(2) or 1)-1
                i+=m.end(); continue
            m=re.match(r'\x1b\[[0-9;]*m', data[i:])
            if m:
                seq=m.group(0)[2:-1]
                params=[p for p in seq.split(';') if p!='']
                j=0
                while j < len(params):
                    p=params[j]
                    if p in ('38','48'):
                        col=None
                        if j+1<len(params) and params[j+1]=='5':
                            col=('idx',int(params[j+2])); j+=3
                        elif j+1<len(params) and params[j+1]=='2':
                            col=('rgb',(int(params[j+2]),int(params[j+3]),int(params[j+4]))); j+=5
                        else:
                            col=('named',int(params[j+1]) if j+1<len(params) else 0); j+=2
                        if p=='38': fg=col
                        else: bg=col
                        continue
                    if p=='0': fg=bg=None; mod=set()
                    elif p=='1': mod.add('bold')
                    elif p=='22': mod.discard('bold'); mod.discard('dim')
                    elif p=='2': mod.add('dim')
                    elif p=='39': fg=None
                    elif p=='49': bg=None
                    elif p=='3': mod.add('italic')
                    elif p=='23': mod.discard('italic')
                    elif p=='4': mod.add('under')
                    elif p=='24': mod.discard('under')
                    else: pass
                    j+=1
                i+=m.end(); continue
            i+=1; continue
        if ch=='\r': c=0; i+=1; continue
        if ch=='\n': r+=1; c=0; i+=1; continue
        if 0<=r<rows and 0<=c<cols:
            grid[r][c]=(ch, (fg,bg,tuple(sorted(mod))))
        c+=1
        if c>=cols: c=cols-1
        i+=1
    return grid

def show(grid, cols, rows, with_style=False):
    for r in range(rows):
        line=''.join(grid[r][c][0] for c in range(cols))
        print(f'{r:2d}|{line.rstrip()}')
        if with_style:
            styles=[]
            for c in range(cols):
                ch,st=grid[r][c]
                if ch.strip()=='' : continue
                styles.append((c,st))
            # compress
            out=[]
            prev=None
            for c,st in styles:
                if st!=prev: out.append((c,st)); prev=st
            print('   styles:', out)

if __name__=='__main__':
    data=open(sys.argv[1],'rb').read().decode('utf8','replace')
    cols=int(sys.argv[2]); rows=int(sys.argv[3])
    pat='\x1b[39m\x1b[49m\x1b[0m\x1b[?25l'
    parts=data.split(pat)
    which=int(sys.argv[4]) if len(sys.argv)>4 else -1
    parts=[p for p in parts if p]
    grid=render(parts[which], cols, rows)
    show(grid, cols, rows, with_style=True)
