{"command": "cd /workspace && cat > src/ig/backend.rs <<'RSEOF'
//! Terminal backend used by igrep.
//!
//! This is a thin adapter around `crossterm` that talks to the terminal using
//! plain ANSI escape sequences. It is intentionally close to the historical
//! ratatui crossterm backend: foreground and background colours are emitted
//! separately and the frame is always terminated by a full colour/attribute
//! reset.

use std::io::{self, Write};

use ratatui::backend::{Backend, ClearType, WindowSize};
use ratatui::layout::{Position, Size};
use ratatui::style::{Color, Modifier};

/// Writer that collects the rendered ANSI output.
pub struct AnsiBackend<W: Write> {
    buffer: W,
    fg: Color,
    bg: Color,
    modifier: Modifier,
    last_pos: Option<Position>,
}

impl<W: Write> AnsiBackend<W> {
    /// Creates a new backend writing into `buffer`.
    pub fn new(buffer: W) -> Self {
        Self {
            buffer,
            fg: Color::Reset,
            bg: Color::Reset,
            modifier: Modifier::empty(),
            last_pos: None,
        }
    }

    /// Returns a mutable reference to the wrapped writer.
    pub fn writer(&mut self) -> &mut W {
        &mut self.buffer
    }

    fn move_to(&mut self, x: u16, y: u16) -> io::Result<()> {
        write!(self.buffer, "\x1b[{};{}H", y + 1, x + 1)
    }

    fn write_fg(&mut self, color: Color) -> io::Result<()> {
        write!(self.buffer, "\x1b[{}", color_code(color, true))
    }

    fn write_bg(&mut self, color: Color) -> io::Result<()> {
        write!(self.buffer, "\x1b[{}", color_code(color, false))
    }

    fn queue_modifier_diff(&mut self, from: Modifier, to: Modifier) -> io::Result<()> {
        let removed = from - to;
        if removed.contains(Modifier::REVERSED) {
            write!(self.buffer, "\x1b[27m")?;
        }

        let reset_intensity = removed.contains(Modifier::BOLD) || removed.contains(Modifier::DIM);
        if reset_intensity {
            write!(self.buffer, "\x1b[22m")?;
            if to.contains(Modifier::DIM) {
                write!(self.buffer, "\x1b[2m")?;
            }
            if to.contains(Modifier::BOLD) {
                write!(self.buffer, "\x1b[1m")?;
            }
        }

        if removed.contains(Modifier::ITALIC) {
            write!(self.buffer, "\x1b[23m")?;
        }
        if removed.contains(Modifier::UNDERLINED) {
            write!(self.buffer, "\x1b[24m")?;
        }
        if removed.contains(Modifier::CROSSED_OUT) {
            write!(self.buffer, "\x1b[29m")?;
        }
        if removed.contains(Modifier::HIDDEN) {
            write!(self.buffer, "\x1b[25m")?;
        }
        if removed.contains(Modifier::SLOW_BLINK) || removed.contains(Modifier::RAPID_BLINK) {
            write!(self.buffer, "\x1b[25m")?;
        }

        let added = to - from;
        if added.contains(Modifier::REVERSED) {
            write!(self.buffer, "\x1b[7m")?;
        }
        if added.contains(Modifier::BOLD) && !reset_intensity {
            write!(self.buffer, "\x1b[1m")?;
        }
        if added.contains(Modifier::ITALIC) {
            write!(self.buffer, "\x1b[3m")?;
        }
        if added.contains(Modifier::UNDERLINED) {
            write!(self.buffer, "\x1b[4m")?;
        }
        if added.contains(Modifier::DIM) && !reset_intensity {
            write!(self.buffer, "\x1b[2m")?;
        }
        if added.contains(Modifier::CROSSED_OUT) {
            write!(self.buffer, "\x1b[9m")?;
        }
        if added.contains(Modifier::HIDDEN) {
            write!(self.buffer, "\x1b[8m")?;
        }
        if added.contains(Modifier::SLOW_BLINK) {
            write!(self.buffer, "\x1b[5m")?;
        }
        if added.contains(Modifier::RAPID_BLINK) {
            write!(self.buffer, "\x1b[6m")?;
        }
        Ok(())
    }
}

/// Encodes a ratatui colour as the argument list of an SGR sequence.
fn color_code(color: Color, foreground: bool) -> String {
    let reset = if foreground { "39" } else { "49" };
    let prefix = if foreground { "38" } else { "48" };
    match color {
        Color::Reset => reset.to_string(),
        Color::Black => format!("{prefix};5;0"),
        Color::Red => format!("{prefix};5;1"),
        Color::Green => format!("{prefix};5;2"),
        Color::Yellow => format!("{prefix};5;3"),
        Color::Blue => format!("{prefix};5;4"),
        Color::Magenta => format!("{prefix};5;5"),
        Color::Cyan => format!("{prefix};5;6"),
        Color::Gray => format!("{prefix};5;7"),
        Color::DarkGray => format!("{prefix};5;8"),
        Color::LightRed => format!("{prefix};5;9"),
        Color::LightGreen => format!("{prefix};5;10"),
        Color::LightYellow => format!("{prefix};5;11"),
        Color::LightBlue => format!("{prefix};5;12"),
        Color::LightMagenta => format!("{prefix};5;13"),
        Color::LightCyan => format!("{prefix};5;14"),
        Color::White => format!("{prefix};5;15"),
        Color::Indexed(i) => format!("{prefix};5;{i}"),
        Color::Rgb(r, g, b) => format!("{prefix};2;{r};{g};{b}"),
    }
}

impl<W: Write> Backend for AnsiBackend<W> {
    type Error = io::Error;

    fn draw<'a, I>(&mut self, content: I) -> io::Result<()>
    where
        I: Iterator<Item = (u16, u16, &'a ratatui::buffer::Cell)>,
    {
        for (x, y, cell) in content {
            if !matches!(self.last_pos, Some(p) if x == p.x + 1 && y == p.y) {
                self.move_to(x, y)?;
            }
            self.last_pos = Some(Position { x, y });
            if cell.modifier != self.modifier {
                let (from, to) = (self.modifier, cell.modifier);
                self.queue_modifier_diff(from, to)?;
                self.modifier = cell.modifier;
            }
            if cell.fg != self.fg {
                self.write_fg(cell.fg)?;
                self.fg = cell.fg;
            }
            if cell.bg != self.bg {
                self.write_bg(cell.bg)?;
                self.bg = cell.bg;
            }
            write!(self.buffer, "{}", cell.symbol())?;
        }

        write!(self.buffer, "\x1b[39m\x1b[49m\x1b[0m")
    }

    fn hide_cursor(&mut self) -> io::Result<()> {
