    pub fn writer(&mut self) -> &mut W {
        &mut self.buffer
    }

    fn move_to(&mut self, x: u16, y: u16) -> io::Result<()> {
        write!(self.buffer, "\x1b[{};{}H", y + 1, x + 1)
    }

    fn write_fg(&mut self, color: Color) -> io::Result<()> {
        write!(self.buffer, "\x1b[{}", color_code(color, true))
    }

    fn write_bg(&mut self, color: Color) -> io::Result<()> {
        write!(self.buffer, "\x1b[{}", color_code(color, false))
    }

    fn queue_modifier_diff(&mut self, from: Modifier, to: Modifier) -> io::Result<()> {
        let removed = from - to;
        if removed.contains(Modifier::REVERSED) {
            write!(self.buffer, "\x1b[27m")?;
        }

