//! Colour themes used by the UI.

use ratatui::style::Color;

/// Palette used for rendering the user interface.
#[derive(Clone, Copy)]
pub struct Theme {
    /// Background of the currently selected match row.
    pub selected_bg: Color,
    /// Foreground used for the status message.
    pub status_fg: Color,
    /// Background used for the status message.
    pub status_bg: Color,
    /// Default foreground used when rendering file contents.
    pub fg: Color,
    /// Colour of comments.
    pub comment: Color,
    /// Colour of keywords.
    pub keyword: Color,
    /// Colour of string literals.
    pub string: Color,
    /// Colour of numbers and constants.
    pub number: Color,
    /// Colour of function names.
    pub function: Color,
    /// Colour of special identifiers (`self`, parameters, ...).
    pub special: Color,
    /// Colour of builtin functions.
    pub builtin: Color,
    /// Colour of type and class names.
    pub class: Color,
    /// Colour of punctuation belonging to a declaration.
    pub punctuation: Color,
}

impl Theme {
    /// Returns the theme with the given name.
    pub fn from_name(name: &str) -> Theme {
        match name {
            "light" => Theme::light(),
            _ => Theme::dark(),
        }
    }

    fn dark() -> Theme {
        Theme {
            selected_bg: Color::Rgb(58, 58, 58),
            status_fg: Color::Rgb(147, 147, 147),
            status_bg: Color::Rgb(58, 58, 58),
            fg: Color::Rgb(192, 197, 206),
            comment: Color::Rgb(101, 115, 126),
            keyword: Color::Rgb(180, 142, 173),
            string: Color::Rgb(163, 190, 140),
            number: Color::Rgb(208, 135, 112),
            function: Color::Rgb(143, 161, 179),
            special: Color::Rgb(191, 97, 106),
            builtin: Color::Rgb(150, 181, 180),
            class: Color::Rgb(235, 203, 139),
            punctuation: Color::Rgb(239, 241, 245),
        }
    }

    fn light() -> Theme {
        Theme {
            selected_bg: Color::Rgb(220, 220, 220),
            status_fg: Color::Reset,
            status_bg: Color::Reset,
            fg: Color::Rgb(79, 91, 102),
            comment: Color::Rgb(167, 173, 186),
            keyword: Color::Rgb(180, 142, 173),
            string: Color::Rgb(163, 190, 140),
            number: Color::Rgb(208, 135, 112),
            function: Color::Rgb(143, 161, 179),
            special: Color::Rgb(191, 97, 106),
            builtin: Color::Rgb(150, 181, 180),
            class: Color::Rgb(208, 135, 112),
            punctuation: Color::Rgb(52, 61, 70),
        }
    }

    /// Colour used for the badge of the running search.
    pub fn searching_badge(&self) -> Color {
        Color::Rgb(255, 165, 0)
    }

    /// Colour used for the badge of a finished search.
    pub fn finished_badge(&self) -> Color {
        Color::Green
    }

    /// Colour used for the badge of an error state.
    pub fn error_badge(&self) -> Color {
        Color::Red
    }

    /// Style applied to the text of a badge.
    pub fn badge_text(&self) -> ratatui::style::Style {
        ratatui::style::Style::new()
            .fg(Color::Black)
            .add_modifier(ratatui::style::Modifier::BOLD)
    }
}
RSEOF
echo ok"}

