//! File type definitions.

use ignore::types::{Types, TypesBuilder};

/// The default file type definitions, one definition per line in the format
/// `name: glob[, glob...]`.
pub const DEFAULT_TYPES: &str = include_str!("default_types.txt");

/// Returns all known type definitions as `(name, globs)` pairs.
pub fn definitions() -> Vec<(String, Vec<String>)> {
    let mut out = Vec::new();
    for line in DEFAULT_TYPES.lines() {
        let line = line.trim_end_matches('\r');
        if line.is_empty() {
            continue;
        }
        let (name, globs) = match line.split_once(": ") {
            Some(v) => v,
            None => continue,
        };
        out.push((
            name.to_string(),
            globs.split(", ").map(|g| g.to_string()).collect(),
        ));
    }
    out
}

/// Renders the type list exactly like the `--type-list` option.
pub fn type_list() -> String {
    let mut out = String::new();
    for (name, globs) in definitions() {
        out.push_str(&name);
        out.push_str(": ");
        out.push_str(&globs.join(", "));
        out.push('\n');
    }
    out
}

/// Builds the type matcher used while walking the file system.
pub fn build_types(include: &[String], exclude: &[String]) -> anyhow::Result<Types> {
    let mut builder = TypesBuilder::new();
    for (name, globs) in definitions() {
        for glob in globs {
            builder.add(&name, &glob).map_err(|e| anyhow::anyhow!("{e}"))?;
        }
    }
    for name in include {
        builder.select(name).map_err(|e| anyhow::anyhow!("{e}"))?;
    }
    for name in exclude {
        builder.negate(name).map_err(|e| anyhow::anyhow!("{e}"))?;
    }
    builder.build().map_err(|e| anyhow::anyhow!("{e}"))
}

/// Returns the glob list of a type definition (used for `--type-list`).
pub fn globs_of(name: &str) -> Option<&'static str> {
    for line in DEFAULT_TYPES.lines() {
        if let Some(rest) = line.strip_prefix(name) {
            if let Some(rest) = rest.strip_prefix(": ") {
                return Some(rest);
            }
        }
    }
    None
}
