use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::PathBuf;
use std::sync::mpsc::Sender;

use ignore::WalkBuilder;
use regex::{Regex, RegexBuilder};

/// Sort order that can be requested for the results.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum SortBy {
    Path,
    Modified,
    Created,
    Accessed,
}

impl SortBy {
    /// Parses the value of the `--sort`/`--sortr` options.
    pub fn from_str(value: &str) -> Option<SortBy> {
        match value {
            "path" => Some(SortBy::Path),
            "modified" => Some(SortBy::Modified),
            "created" => Some(SortBy::Created),
            "accessed" => Some(SortBy::Accessed),
            _ => None,
        }
    }
}

/// Options controlling a single search run.
#[derive(Clone)]
pub struct SearchOptions {
    /// Files and directories to search.
    pub paths: Vec<PathBuf>,
    /// Searches case insensitively.
    pub ignore_case: bool,
    /// Searches case insensitively when the pattern is lowercase.
    pub smart_case: bool,
    /// Only show matches surrounded by word boundaries.
    pub word_regexp: bool,
    /// Treat the pattern as a literal string.
    pub fixed_strings: bool,
    /// Allow the pattern to span multiple lines.
    pub multiline: bool,
    /// Search hidden files and directories.
    pub hidden: bool,
    /// Follow symbolic links while traversing directories.
    pub follow: bool,
    /// Include files matching these globs.
    pub globs: Vec<String>,
    /// Only search files of these types.
    pub types: Vec<String>,
    /// Do not search files of these types.
    pub types_not: Vec<String>,
    /// Sort order of the results.
    pub sort: Option<SortBy>,
    /// Whether the sort order should be reversed.
    pub sort_reverse: bool,
}

/// A single match inside a line.
#[derive(Clone, Eq, PartialEq)]
pub struct Span {
    /// Start of the match, in bytes.
    pub start: usize,
    /// End of the match, in bytes.
    pub end: usize,
}

/// A matching line.
#[derive(Clone, Eq, PartialEq)]
pub struct Match {
    /// 1-based line number.
    pub line_number: u64,
    /// Content of the line (without the trailing newline).
    pub text: String,
    /// All matches found in this line.
    pub spans: Vec<Span>,
}

/// Results of a single file.
#[derive(Clone, Eq, PartialEq)]
pub struct FileMatches {
    /// Path of the file, as produced by the directory walker.
    pub path: PathBuf,
    /// Matches in the order they appear in the file.
    pub matches: Vec<Match>,
}

/// Message sent from the search thread to the UI.
#[derive(Clone, Eq, PartialEq)]
pub enum SearchEvent {
    /// A file with at least one match was found.
    Found(FileMatches),
    /// The search has completed.
    Done,
}

/// Builds the regular expression used for the search.
fn build_pattern(options: &SearchOptions) -> String {
    let pattern = if options.fixed_strings {
        regex::escape(&options.pattern)
    } else {
        options.pattern.clone()
    };
    let mut expr = if options.word_regexp {
        format!(r"(?:\b(?:{})\b)", pattern)
    } else {
        format!(r"(?:{})", pattern)
    };
    if options.ignore_case
        || (options.smart_case && !options.pattern.chars().any(|c| c.is_uppercase()))
    {
        expr = format!("(?i){}", expr);
    }
    expr
}

/// Compiles the search pattern, panicking when it is not a valid expression.
fn build_matcher(options: &SearchOptions) -> Regex {
    let expr = build_pattern(options);
    RegexBuilder::new(&expr)
        .size_limit(10 * (1 << 20))
        .build()
        .expect("Cannot build RegexMatcher")
}

fn search_file(path: &PathBuf, re: &Regex) -> Option<FileMatches> {
    let file = File::open(path).ok()?;
    let mut reader = BufReader::new(file);
    let mut buffer = Vec::new();
    let mut matches = Vec::new();
    let mut line_number: u64 = 0;
    while let Ok(n) = reader.read_until(b'\n', &mut buffer) {
        if n == 0 {
            break;
        }
        line_number += 1;
        if buffer.contains(&b'\0') {
            return None;
        }
        if buffer.ends_with(b"\n") {
            buffer.pop();
            if buffer.ends_with(b"\r") {
                buffer.pop();
            }
        }
        let text = match std::str::from_utf8(&buffer) {
            Ok(t) => t.to_string(),
            Err(_) => {
                buffer.clear();
                continue;
            }
        };
        buffer.clear();
        let mut spans = Vec::new();
        let mut last = 0usize;
        for mat in re.find_iter(&text) {
            if mat.start() < last {
                continue;
            }
            last = mat.end();
            spans.push(Span {
                start: mat.start(),
                end: mat.end(),
            });
        }
        if !spans.is_empty() {
            matches.push(Match {
                line_number,
                text,
                spans,
            });
        }
    }
    if matches.is_empty() {
        None
    } else {
        Some(FileMatches {
            path: path.clone(),
            matches,
        })
    }
}

/// Runs the search and streams the results through `sender`.
pub fn search(options: SearchOptions, sender: Sender<SearchEvent>) {
    std::thread::spawn(move || {
        let types = match crate_types(&options) {
            Ok(t) => t,
            Err(_) => {
                let _ = sender.send(SearchEvent::Done);
                return;
            }
        };
        let mut builder = WalkBuilder::new(root(&options));
        builder.hidden(!options.hidden);
        builder.follow_links(options.follow);
        builder.git_ignore(true);
        builder.git_global(true);
        builder.ignore(true);
        builder.parents(true);
        builder.overrides(overrides(&options));
        builder.types(types);
        builder.threads(std::thread::available_parallelism().map_or(4, |n| n.get()));
        builder.build_parallel().run(|| Visitor {
            re: None,
            options: options.clone(),
            sender: sender.clone(),
        });
        let _ = sender.send(SearchEvent::Done);
    });
}

fn root(options: &SearchOptions) -> PathBuf {
    options
        .paths
        .first()
        .cloned()
        .unwrap_or_else(|| PathBuf::from("."))
}

fn crate_types(
    options: &SearchOptions,
) -> anyhow::Result<ignore::types::Types> {
    crate::types::build_types(&options.types, &options.types_not)
}

fn overrides(options: &SearchOptions) -> ignore::overrides::Override {
    let mut builder = ignore::overrides::OverrideBuilder::new(".");
    for glob in &options.globs {
        let _ = builder.add(glob);
    }
    builder.build().unwrap_or_default()
}

struct Visitor {
    re: Option<Regex>,
    options: SearchOptions,
    sender: Sender<SearchEvent>,
}

impl ignore::WalkParallel::Visitor for Visitor {
    fn visit(&mut self, entry: Result<ignore::DirEntry, ignore::Error>) -> ignore::WalkState {
        use ignore::WalkState::Continue;
        let entry = match entry {
            Ok(e) => e,
            Err(_) => return Continue,
        };
        if !entry.file_type().map_or(false, |t| t.is_file()) {
            return Continue;
        }
        if self.re.is_none() {
            self.re = Some(build_matcher(&self.options));
        }
        let re = self.re.as_ref().unwrap();
        if let Some(found) = search_file(&entry.path().to_path_buf(), re) {
