    /// Matches in the order they appear in the file.
    pub matches: Vec<Match>,
}

/// Message sent from the search thread to the user interface.
#[derive(Clone, Eq, PartialEq)]
pub enum SearchEvent {
    /// A file with at least one match was found.
    Found(FileMatches),
    /// The search has completed.
    Done,
}

impl SearchOptions {
    /// Builds the override matcher used to include files explicitly.
    fn overrides(&self) -> ignore::overrides::Override {
        let mut builder = OverrideBuilder::new(".");
        for glob in &self.globs {
            let _ = builder.add(glob);
        }
        builder.build().unwrap_or_default()
    }

    /// Builds the type matcher used to filter files by type.
    fn types(&self) -> anyhow::Result<Types> {
        crate::types::build_types(&self.types, &self.types_not)
    }
}

/// Runs the search and streams the results through `sender`.
///
/// The walk is parallel: every worker picks up entries as they become
/// available, so results are emitted in an unspecified order unless a sort
/// order is requested.
pub fn search(options: SearchOptions, sender: Sender<SearchEvent>) {
    let overrides = options.overrides();
    let types = match options.types() {
        Ok(types) => types,
        Err(_) => {
            let _ = sender.send(SearchEvent::Done);
            return;
        }
    };
    let roots = if options.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        options.paths.clone()
    };
    let threads = std::thread::available_parallelism().map_or(4, |n| n.get());
    std::thread::spawn(move || {
        let re = compile(&options);
        for root in roots {
            let mut builder = WalkBuilder::new(&root);
            builder.hidden(!options.hidden);
            builder.follow_links(options.follow);
            builder.git_ignore(true);
            builder.git_global(true);
            builder.ignore(true);
            builder.parents(true);
            builder.overrides(overrides.clone());
            builder.types(types.clone());
            builder.threads(threads);
            builder.build_parallel().run(|| Visitor {
                re: &re,
                sender: sender.clone(),
            });
        }
        let _ = sender.send(SearchEvent::Done);
    });
}

struct Visitor<'a> {
    re: &'a Regex,
    sender: Sender<SearchEvent>,
}

impl ignore::WalkParallelVisitor for Visitor<'_> {
    fn visit(&mut self, entry: Result<ignore::DirEntry, ignore::Error>) -> ignore::WalkState {
        use ignore::WalkState::Continue;
        let entry = match entry {
            Ok(entry) => entry,
            Err(_) => return Continue,
        };
        if !entry.file_type().map_or(false, |t| t.is_file()) {
            return Continue;
        }
        if let Some(found) = search_file(&entry.path().to_path_buf(), self.re) {
            let _ = self.sender.send(SearchEvent::Found(found));
        }
        Continue
    }
}

/// Searches a single file, returning `None` when it holds no matches or when
/// it should be skipped (binary content, invalid UTF-8, ...).
fn search_file(path: &PathBuf, re: &Regex) -> Option<FileMatches> {
    let file = File::open(path).ok()?;
    let mut reader = BufReader::new(file);
    let mut buffer: Vec<u8> = Vec::new();
    let mut matches: Vec<Match> = Vec::new();
    let mut line_number: u64 = 0;
    loop {
        buffer.clear();
        let read = reader.read_until(b'\n', &mut buffer).ok()?;
        if read == 0 {
            break;
        }
        line_number += 1;
        if buffer.contains(&b'\0') {
            return None;
        }
        if buffer.ends_with(b"\n") {
            buffer.pop();
            if buffer.ends_with(b"\r") {
                buffer.pop();
            }
        }
        let text = match std::str::from_utf8(&buffer) {
            Ok(text) => text.to_string(),
            Err(_) => continue,
        };
        let mut spans = Vec::new();
        for mat in re.find_iter(&text) {
            spans.push(Span {
                start: mat.start(),
                end: mat.end(),
            });
        }
        if !spans.is_empty() {
            matches.push(Match {
                line_number,
                text,
                spans,
            });
        }
    }
    if matches.is_empty() {
        None
    } else {
        Some(FileMatches {
            path: path.clone(),
            matches,
        })
    }
}
