        "fresh" => "fresh {file_name}:{line_number}",
        _ => return None,
    })
}

/// Returns the list of editor names accepted by `--editor`.
pub fn preset_names() -> &'static [&'static str] {
    &[
        "vim",
        "neovim",
        "nvim",
        "nano",
        "code",
        "vscode",
        "code-insiders",
        "emacs",
        "emacsclient",
        "hx",
        "helix",
        "subl",
        "sublime-text",
        "micro",
        "intellij",
        "goland",
        "pycharm",
        "less",
        "fresh",
    ]
}

impl EditorSpec {
    /// Parses a `--editor` value.
    pub fn from_preset(name: &str) -> Option<EditorSpec> {
        if preset_names().contains(&name) {
            Some(EditorSpec::Preset(
                preset_command(name).unwrap_or_default(),
            ))
        } else {
            None
        }
    }

    /// Validates a custom command, returning the program and its arguments.
    pub fn parse_custom(command: &str) -> Result<(String, Vec<String>)> {
        let err = || anyhow!("Incorrect editor command: '{command}'");
        let (program, rest) = command
            .split_once(' ')
            .ok_or_else(|| err().context("Expected program and its arguments"))?;
        for token in ["{file_name}", "{line_number}"] {
            if command.matches(token).count() != 1 {
                bail!(err().context(format!("Expected one occurrence of '{token}'.")));
            }
        }
        Ok((
            program.to_string(),
            rest.split(' ').map(|a| a.to_string()).collect(),
        ))
    }

    /// Name of the editor, used in error messages.
    pub fn name(&self) -> String {
        match self {
            EditorSpec::Preset(command) => command
                .split(' ')
                .next()
                .unwrap_or_default()
                .to_string(),
            EditorSpec::Custom(command) => command
                .split(' ')
                .next()
                .unwrap_or_default()
                .to_string(),
        }
    }

    /// Builds the command that opens `file_name` at `line_number`.
    pub fn command(&self, file_name: &str, line_number: u64) -> Result<Command> {
        let (program, args) = match self {
            EditorSpec::Preset(template) => {
                let rendered = template
                    .replace("{file_name}", file_name)
                    .replace("{line_number}", &line_number.to_string());
                split_command(&rendered)
            }
            EditorSpec::Custom(command) => {
                let rendered = command
                    .replace("{file_name}", file_name)
                    .replace("{line_number}", &line_number.to_string());
                split_command(&rendered)
            }
        };
        let mut parts = args.into_iter();
        let program = parts.next().ok_or_else(|| {
            anyhow!("Incorrect editor command: '{}'", self.name())
        })?;
        let mut command = Command::new(program);
        command.args(parts);
        Ok(command)
    }
}

/// Splits a command into the program and its arguments.
fn split_command(command: &str) -> (String, Vec<String>) {
    let mut parts = command.split(' ');
    let program = parts.next().unwrap_or_default().to_string();
    (
        program,
        parts.filter(|p| !p.is_empty()).map(|p| p.to_string()).collect(),
    )
}
