{"command": "cd /workspace && cat > src/ig/syntax.rs <<'RSEOF'
//! Lightweight syntax highlighting used by the context viewer.
//!
//! The highlighter is intentionally simple: it walks a line token by token and
//! assigns one of the theme colours to every token. A small amount of state is
//! carried over between lines so that block comments and multi line strings
//! keep their colour.

use std::path::Path;

use crate::theme::Theme;

/// Kind of token that was recognized.
#[derive(Clone, Copy, Eq, PartialEq)]
pub enum Kind {
    Comment,
    Str,
    Number,
    Keyword,
    Function,
    Special,
    Builtin,
    Class,
    Punctuation,
    Plain,
}

/// A token of a highlighted line.
#[derive(Clone, Eq, PartialEq)]
pub struct Token {
    /// Start of the token, in bytes.
    pub start: usize,
    /// End of the token, in bytes.
    pub end: usize,
    /// Kind of the token.
    pub kind: Kind,
}

/// A language definition used by the highlighter.
struct Language {
    keywords: &'static [&'static str],
    builtins: &'static [&'static str],
    constants: &'static [&'static str],
    line_comment: Option<&'static str>,
    block_comment: Option<(&'static str, &'static str)>,
    /// Quotes that open a single line string.
    quotes: &'static [char],
    /// Quotes that open a multi line string (rendered like a comment).
    multi_quotes: &'static [&'static str],
}

const PYTHON_KEYWORDS: &[&str] = &[
    "assert", "await", "break", "class", "continue", "def", "del", "elif", "else", "except",
    "finally", "for", "from", "global", "if", "import", "lambda", "nonlocal", "pass", "raise",
    "return", "while", "with", "yield",
];

const PYTHON_BUILTINS: &[&str] = &[
    "abs", "all", "any", "bin", "bool", "bytearray", "bytes", "callable", "chr", "classmethod",
    "compile", "complex", "delattr", "dict", "dir", "divmod", "enumerate", "eval", "filter",
    "float", "format", "frozenset", "getattr", "globals", "hasattr", "hash", "hex", "id", "input",
    "int", "isinstance", "issubclass", "iter", "len", "list", "locals", "map", "max", "memoryview",
    "min", "next", "object", "oct", "open", "ord", "pow", "print", "property", "range", "repr",
    "reversed", "round", "set", "setattr", "slice", "sorted", "staticmethod", "str", "sum",
    "super", "tuple", "type", "vars", "zip",
];

const RUST_KEYWORDS: &[&str] = &[
    "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum", "extern",
    "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub",
    "ref", "return", "static", "struct", "super", "trait", "true", "type", "unsafe", "use", "where",
    "while", "yield",
];

const RUST_BUILTINS: &[&str] = &[
    "assert", "assert_eq", "assert_ne", "debug_assert", "env", "panic", "print", "println",
    "vec", "write", "writeln",
];

fn languages() -> Vec<(&'static str, Language)> {
    vec![
        (
            "python",
            Language {
                keywords: PYTHON_KEYWORDS,
                builtins: PYTHON_BUILTINS,
                constants: &["True", "False", "None"],
                line_comment: Some("#"),
                block_comment: None,
                quotes: &['"', '\''],
                multi_quotes: &["\"\"\"", "'''"],
            },
        ),
        (
            "rust",
            Language {
                keywords: RUST_KEYWORDS,
                builtins: RUST_BUILTINS,
                constants: &["true", "false", "None", "Some", "Ok", "Err"],
                line_comment: Some("//"),
                block_comment: Some(("/*", "*/")),
                quotes: &['"', '\''],
                multi_quotes: &[],
            },
        ),
    ]
}

/// Returns the language matching a file path, if any.
fn language_for(path: &Path) -> Option<&'static str> {
    let ext = path.extension()?.to_string_lossy().to_lowercase();
    let name = match ext.as_str() {
        "py" | "pyi" | "pyw" => "python",
        "rs" => "rust",
        _ => return None,
    };
    Some(name)
}

/// Highlights one line, returning the recognized tokens.
pub fn highlight(path: &Path, line: &str, state: &mut State) -> Vec<Token> {
    let language = language_for(path);
    let mut tokens: Vec<Token> = Vec::new();
    let Some(name) = language else {
        return tokens;
    };
    let (_key, lang) = languages()
        .into_iter()
        .find(|(key, _)| *key == name)
        .unwrap();
    let bytes = line.as_bytes();
    let mut i = 0usize;
    // A block comment or multi line string may have been started on an
    // earlier line.
    if let Some(kind) = state.pending {
        let end = match kind {
            Kind::Comment => lang.block_comment.map(|c| c.1),
            Kind::Str => None,
            _ => None,
        };
        match end {
            Some(end) => {
                if let Some(pos) = find(line, end, 0) {
                    tokens.push(Token {
                        start: 0,
                        end: pos + end.len(),
                        kind,
                    });
                    state.pending = None;
                    i = pos + end.len();
                } else {
                    tokens.push(Token {
                        start: 0,
                        end: line.len(),
                        kind,
                    });
                    return tokens;
                }
            }
            None => {
                tokens.push(Token {
                    start: 0,
                    end: line.len(),
                    kind,
                });
                return tokens;
            }
        }
    }
    let mut expecting_name: Option<Kind> = None;
    while i < bytes.len() {
        if let Some(comment) = lang.line_comment {
            if starts_with(line, comment, i) {
                tokens.push(Token {
                    start: i,
                    end: line.len(),
                    kind: Kind::Comment,
                });
                break;
            }
        }
        if let Some((open, close)) = lang.block_comment {
            if starts_with(line, open, i) {
                if let Some(pos) = find(line, close, i + open.len()) {
                    tokens.push(Token {
                        start: i,
                        end: pos + close.len(),
                        kind: Kind::Comment,
                    });
                    i = pos + close.len();
                    continue;
                }
                tokens.push(Token {
                    start: i,
                    end: line.len(),
                    kind: Kind::Comment,
                });
                state.pending = Some(Kind::Comment);
                break;
            }
        }
        for multi in lang.multi_quotes {
            if starts_with(line, multi, i) {
                if let Some(pos) = find(line, multi, i + multi.len()) {
                    tokens.push(Token {
                        start: i,
                        end: pos + multi.len(),
                        kind: Kind::Comment,
                    });
                    i = pos + multi.len();
                } else {
                    tokens.push(Token {
                        start: i,
                        end: line.len(),
                        kind: Kind::Comment,
                    });
                    state.pending = Some(Kind::Comment);
                    i = line.len();
                }
                break;
            }
        }
        if i < bytes.len() && lang.quotes.contains(&(bytes[i] as char)) {
            let quote = bytes[i] as char;
            let mut j = i + 1;
            let mut escaped = false;
            while j < bytes.len() {
                let c = bytes[j] as char;
                if escaped {
                    escaped = false;
                } else if c == '\\' {
                    escaped = true;
                } else if c == quote {
                    break;
                }
                j += 1;
            }
            let end = (j + 1).min(line.len());
            tokens.push(Token {
                start: i + 1,
                end: j.min(line.len()),
                kind: Kind::Str,
            });
            i = end;
            continue;
        }
        if i < bytes.len() && bytes[i].is_ascii_digit() {
            let mut j = i;
            while j < bytes.len() && is_number_byte(bytes[j]) {
                j += 1;
            }
            tokens.push(Token {
                start: i,
                end: j,
                kind: Kind::Number,
            });
            i = j;
            continue;
        }
        if is_word_start(bytes[i]) {
            let mut j = i;
            while j < bytes.len() && is_word_byte(bytes[j]) {
                j += 1;
            }
            let word = &line[i..j];
            let kind = if lang.keywords.contains(&word) {
                Kind::Keyword
            } else if lang.constants.contains(&word) {
                Kind::Number
            } else if let Some(expected) = expecting_name {
                expecting_name = None;
                expected
            } else if next_is_call(line, j) {
                if lang.builtins.contains(&word) {
                    Kind::Builtin
                } else {
                    Kind::Function
                }
            } else if word == "self" || word == "cls" {
                Kind::Special
            } else {
                Kind::Plain
            };
            tokens.push(Token {
                start: i,
                end: j,
                kind,
            });
            if kind == Kind::Keyword {
                expecting_name = match word {
                    "def" | "fn" | "func" | "function" | "sub" => Some(Kind::Function),
                    "class" | "struct" | "enum" | "interface" | "type" => Some(Kind::Class),
                    _ => None,
                };
            }
            i = j;
            continue;
        }
        i += 1;
    }
    tokens
}

/// Highlighting state carried over between lines.
#[derive(Clone, Eq, PartialEq, Default)]
pub struct State {
    pending: Option<Kind>,
}

fn is_number_byte(b: u8) -> bool {
    b.is_ascii_digit() || matches!(b, b'_' | b'.' | b'x' | b'X' | b'o' | b'b' | b'a' | b'c' | b'd' | b'e' | b'f' | b'A' | b'B' | b'C' | b'D' | b'E' | b'F' | b'+')
}

fn is_word_start(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_' || b >= 0x80
}

fn is_word_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b >= 0x80
}

fn starts_with(line: &str, needle: &str, at: usize) -> bool {
    line.len() >= at + needle.len() && &line[at..at + needle.len()] == needle
}

fn find(line: &str, needle: &str, from: usize) -> Option<usize> {
    if from > line.len() {
        return None;
    }
    line[from..].find(needle).map(|p| p + from)
}

fn next_is_call(line: &str, at: usize) -> bool {
    let bytes = line.as_bytes();
    let mut k = at;
    while k < bytes.len() && (bytes[k] == b' ' || bytes[k] == b'\t') {
        k += 1;
    }
    k < bytes.len() && bytes[k] == b'('
}

/// Maps a token kind to the colour used by the theme.
pub fn color(kind: Kind, theme: &Theme) -> ratatui::style::Color {
    match kind {
        Kind::Comment => theme.comment,
        Kind::Str => theme.string,
        Kind::Number => theme.number,
        Kind::Keyword => theme.keyword,
        Kind::Function => theme.function,
        Kind::Special => theme.special,
        Kind::Builtin => theme.builtin,
        Kind::Class => theme.class,
        Kind::Punctuation => theme.punctuation,
        Kind::Plain => theme.fg,
    }
}
