//! Application state and key bindings.

use std::path::PathBuf;
use std::sync::mpsc::{self, Receiver, Sender, TryRecvError};

use crate::editor::EditorSpec;
use crate::searcher::{FileMatches, Match, SearchEvent, SearchOptions, SortBy};
use crate::theme::Theme;

/// Which popup is currently shown, if any.
#[derive(Clone, Eq, PartialEq)]
pub enum Popup {
    /// No popup.
    None,
    /// The keymap overview.
    Keymap {
        /// Vertical scroll offset.
        offset_y: usize,
        /// Horizontal scroll offset.
        offset_x: usize,
    },
    /// The search pattern input.
    Search {
        /// Current contents of the input.
        value: String,
    },
}

/// Position of the context viewer.
#[derive(Clone, Copy, Eq, PartialEq)]
pub enum ContextViewer {
    /// Not shown.
    None,
    /// Shown to the right of the results.
    Vertical,
    /// Shown below the results.
    Horizontal,
}

/// Status shown in the bottom line of the UI.
#[derive(Clone, Eq, PartialEq)]
pub enum Status {
    /// The search is still running; holds the number of matches found so far.
    Searching(usize),
    /// The search has finished.
    Finished {
        /// Number of visible matches.
        matches: usize,
        /// Number of files that were searched.
        files: usize,
        /// Number of matches that were filtered out.
        filtered: usize,
    },
    /// An error occurred.
    Error(String),
}

/// A row of the results list.
#[derive(Clone, Eq, PartialEq)]
pub enum Item {
    /// Header of a file.
    File(usize),
    /// A match inside a file.
    Match(usize, usize),
}

/// Whole application state.
pub struct App {
    /// Options of the current search.
    pub options: SearchOptions,
    /// Pattern of the current search.
    pub pattern: String,
    /// Results in the order they are displayed.
    pub results: Vec<FileMatches>,
    /// Flattened rows of the results list.
    pub items: Vec<Item>,
    /// Index of the selected row.
    pub selected: usize,
    /// Scroll offset of the results list.
    pub offset: usize,
    /// Status of the search.
    pub status: Status,
    /// Colour theme.
    pub theme: Theme,
    /// How matches are opened.
    pub editor: EditorSpec,
    /// Position of the context viewer.
    pub context: ContextViewer,
    /// Relative size of the context viewer, in percent.
    pub viewer_size: u16,
    /// Popup that is currently shown.
    pub popup: Popup,
    /// Key sequence that is waiting to be completed.
    pub pending: Vec<char>,
    /// Horizontal scroll offset of the context viewer.
    pub viewer_offset_x: usize,
    /// Receiver of search events.
    pub receiver: Option<Receiver<SearchEvent>>,
    /// Sender of search events.
    pub sender: Sender<SearchEvent>,
    /// Whether a search is currently running.
    pub searching: bool,
}

impl App {
    /// Creates the initial state and starts the first search.
    pub fn new(options: SearchOptions, pattern: String, theme: Theme, editor: EditorSpec) -> App {
        let (sender, receiver) = mpsc::channel();
        let mut app = App {
            pattern,
            items: Vec::new(),
            selected: 0,
            offset: 0,
            status: Status::Searching(0),
            theme,
            editor,
            context: ContextViewer::None,
            viewer_size: 50,
            popup: Popup::None,
            pending: Vec::new(),
            viewer_offset_x: 0,
            receiver: None,
            sender: sender.clone(),
            searching: true,
            options,
            results: Vec::new(),
        };
        crate::searcher::search(app.options.clone(), sender);
        app.receiver = Some(receiver);
        app
    }

    /// Drains all events that have arrived so far.
    pub fn poll(&mut self) {
        let Some(receiver) = self.receiver.as_ref() else {
            return;
        };
        loop {
            match receiver.try_recv() {
                Ok(SearchEvent::Found(found)) => {
                    self.results.push(found);
                }
                Ok(SearchEvent::Done) => {
                    self.searching = false;
                    self.receiver = None;
                    self.finish();
                    break;
                }
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => {
                    self.searching = false;
                    self.receiver = None;
                    self.finish();
                    break;
                }
            }
        }
    }

    /// Applies the requested sort order and rebuilds the item list.
    pub fn finish(&mut self) {
        if let Some(sort) = self.options.sort {
            sort_results(&mut self.results, sort, self.options.sort_reverse);
        }
        self.rebuild();
        let matches: usize = self.results.iter().map(|f| f.matches.len()).sum();
        self.status = Status::Finished {
            matches,
            files: self.results.len(),
            filtered: 0,
        };
        if !self.items.is_empty() {
            self.select(1);
        }
    }

    /// Rebuilds the flattened item list from the results.
    pub fn rebuild(&mut self) {
        self.items.clear();
        for (file, result) in self.results.iter().enumerate() {
            self.items.push(Item::File(file));
            for (index, _) in result.matches.iter().enumerate() {
                self.items.push(Item::Match(file, index));
            }
        }
        if self.selected >= self.items.len() {
            self.selected = self.items.len().saturating_sub(1);
        }
    }

