                Err(TryRecvError::Disconnected) => {
                    self.searching = false;
                    self.receiver = None;
                    self.finish();
                    break;
                }
            }
        }
    }

    /// Applies the requested sort order and rebuilds the item list.
    pub fn finish(&mut self) {
        if let Some(sort) = self.options.sort {
            sort_results(&mut self.results, sort, self.options.sort_reverse);
        }
        self.rebuild();
        let matches: usize = self.results.iter().map(|f| f.matches.len()).sum();
        self.status = Status::Finished {
            matches,
            files: self.results.len(),
            filtered: 0,
        };
        if !self.items.is_empty() {
            self.select(1);
        }
    }

    /// Rebuilds the flattened item list from the results.
    pub fn rebuild(&mut self) {
        self.items.clear();
        for (file, result) in self.results.iter().enumerate() {
            self.items.push(Item::File(file));
            for (index, _) in result.matches.iter().enumerate() {
                self.items.push(Item::Match(file, index));
            }
        }
        if self.selected >= self.items.len() {
            self.selected = self.items.len().saturating_sub(1);
        }
    }

    /// Number of matches that are currently visible.
    pub fn visible_matches(&self) -> usize {
        self.items.iter().filter(|i| matches!(i, Item::Match(_, _))).count()
    }

    /// Number of files that are currently visible.
    pub fn visible_files(&self) -> usize {
        self.items.iter().filter(|i| matches!(i, Item::File(_))).count()
    }

    /// Index of the selected item, 0 when the list is empty.
    pub fn selected_index(&self) -> usize {
        self.selected
    }

    /// Selects a row by index, keeping it visible.
    pub fn select(&mut self, index: usize) {
        if self.items.is_empty() {
            self.selected = 0;
            self.offset = 0;
            return;
        }
        let index = index.min(self.items.len() - 1);
        self.selected = index;
    }

    /// Selects the next match.
    pub fn next_match(&mut self) {
        if self.selected + 1 < self.items.len() {
            self.selected += 1;
        }
    }

    /// Selects the previous match.
    pub fn previous_match(&mut self) {
        self.selected = self.selected.saturating_sub(1);
    }

    /// Selects the first match.
    pub fn first_match(&mut self) {
        self.select(0);
    }

    /// Selects the last match.
    pub fn last_match(&mut self) {
        self.select(self.items.len().saturating_sub(1));
    }

    /// Selects the first match of the next file.
    pub fn next_file(&mut self) {
        let current = self.current_file();
        for (index, item) in self.items.iter().enumerate().skip(self.selected + 1) {
            if let Item::File(file) = item {
                if *file != current {
                    self.selected = index + 1;
                    return;
                }
            }
        }
    }

    /// Selects the first match of the previous file.
    pub fn previous_file(&mut self) {
        let current = self.current_file();
        for index in (0..self.selected).rev() {
            if let Item::File(file) = self.items[index] {
                if file != current {
                    self.selected = (index + 1).min(self.items.len().saturating_sub(1));
                    return;
                }
            }
        }
    }

    /// File index of the selected row.
    pub fn current_file(&self) -> usize {
        match self.items.get(self.selected) {
            Some(Item::File(file)) => *file,
            Some(Item::Match(file, _)) => *file,
            None => 0,
        }
    }

    /// Match of the selected row.
    pub fn current_match(&self) -> Option<(usize, usize)> {
        match self.items.get(self.selected) {
            Some(Item::Match(file, index)) => Some((*file, *index)),
            _ => None,
        }
    }

    /// Filters out the selected match.
    pub fn filter_selected(&mut self) {
        let Some((file, index)) = self.current_match() else {
            return;
        };
        let next = self.selected + 1;
        self.results[file].matches.remove(index);
        let filtered = self.filtered_out() + 1;
        self.rebuild();
        self.set_filtered(filtered);
        if next < self.items.len() {
            self.selected = next;
        } else {
            self.selected = self.items.len().saturating_sub(1);
        }
    }

    /// Filters out every match of the selected file.
    pub fn filter_file(&mut self) {
        let file = self.current_file();
        let removed = self.results[file].matches.len();
        if removed == 0 {
            return;
        }
        self.results[file].matches.clear();
        let filtered = self.filtered_out() + removed;
        self.rebuild();
        self.set_filtered(filtered);
        let next = self
            .items
            .iter()
            .position(|i| matches!(i, Item::Match(f, _)) if *f != file);
        match next {
            Some(index) => self.selected = index,
            None => self.select(self.items.len().saturating_sub(1)),
        }
    }

    /// Number of matches that have been filtered out.
    pub fn filtered_out(&self) -> usize {
        match self.status {
            Status::Finished { filtered, .. } => filtered,
            _ => 0,
        }
    }

    fn set_filtered(&mut self, filtered: usize) {
        if let Status::Finished { matches, files, .. } = self.status {
            self.status = Status::Finished {
                matches: self.visible_matches(),
                files,
                filtered,
            };
            let _ = matches;
        }
    }

    /// Applies a new sort order.
    pub fn sort_by(&mut self, sort: SortBy, reverse: bool) {
        self.options.sort = Some(sort);
        self.options.sort_reverse = reverse;
        let selected_path = self.selected_path();
        sort_results(&mut self.results, sort, reverse);
        self.rebuild();
        if let Some(path) = selected_path {
            if let Some(index) = self.items.iter().position(|item| match item {
                Item::Match(file, index) => {
                    self.results[*file].matches[*index].line_number
                        == self.results[file].matches[*index].line_number
                        && self.results[*file].path == path
                }
                _ => false,
            }) {
                self.selected = index;
            }
        }
    }

    fn selected_path(&self) -> Option<PathBuf> {
        self.current_match().map(|(file, _)| self.results[file].path.clone())
    }

    /// Restarts the search with a new pattern.
    pub fn search(&mut self, pattern: String) {
        self.pattern = pattern.clone();
        self.options.pattern = pattern;
        self.results.clear();
        self.items.clear();
        self.selected = 0;
        self.offset = 0;
        self.pending.clear();
        self.searching = true;
        self.status = Status::Searching(0);
        let (sender, receiver) = mpsc::channel();
        self.sender = sender.clone();
        crate::searcher::search(self.options.clone(), sender);
        self.receiver = Some(receiver);
    }

    /// Starts the search again with the current pattern.
    pub fn research(&mut self) {
        self.search(self.pattern.clone());
    }
}

fn sort_results(results: &mut [FileMatches], sort: SortBy, reverse: bool) {
    results.sort_by(|a, b| {
        let ordering = match sort {
            SortBy::Path => a.path.cmp(&b.path),
            SortBy::Modified => modified(&a.path).cmp(&modified(&b.path)),
            SortBy::Created => created(&a.path).cmp(&created(&b.path)),
            SortBy::Accessed => accessed(&a.path).cmp(&accessed(&b.path)),
        };
        if reverse {
            ordering.reverse()
        } else {
            ordering
        }
    });
}

fn metadata(path: &PathBuf) -> Option<std::fs::Metadata> {
    std::fs::metadata(path).ok()
}

fn modified(path: &PathBuf) -> std::time::SystemTime {
    metadata(path).and_then(|m| m.modified().ok()).unwrap_or(std::time::UNIX_EPOCH)
}

fn created(path: &PathBuf) -> std::time::SystemTime {
    metadata(path).and_then(|m| m.created().ok()).unwrap_or(std::time::UNIX_EPOCH)
}

fn accessed(path: &PathBuf) -> std::time::SystemTime {
    metadata(path).and_then(|m| m.accessed().ok()).unwrap_or(std::time::UNIX_EPOCH)
}

/// Text shown in the status line for a finished search.
pub fn finished_message(matches: usize, files: usize, filtered: usize) -> String {
    if matches == 0 {
        "No matches found.".to_string()
    } else {
        let mut text = format!(
            " Found {} {} in {} {}",
            matches,
            if matches == 1 { "match" } else { "matches" },
            files,
            if files == 1 { "file" } else { "files" },
        );
        if filtered > 0 {
            text.push_str(&format!(" ({} filtered out)", filtered));
        }
        text.push('.');
        text
    }
}
