//! Rendering of the user interface.

use ratatui::buffer::Buffer;
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Widget};

use crate::app::{App, ContextViewer, Item, Popup, Status};
use crate::backend::AnsiBackend;
use crate::syntax::{self, Kind};
use crate::theme::Theme;

/// Version string shown in the title of the keymap popup.
pub const VERSION: &str = "1.3.0";

/// Keymap entries shown in the keymap popup.
const KEYMAP: &[(&str, &str)] = &[
    ("q, Esc, Ctrl+c", "Quit"),
    ("", ""),
    ("?, F1", "Open/close the keymap popup"),
    ("Down, j", "Scroll down in the keymap popup"),
    ("Up, k", "Scroll up in the keymap popup"),
    ("Right, l", "Scroll right in the keymap popup"),
    ("Left, h", "Scroll left in the keymap popup"),
    ("", ""),
    ("Down, j", "Select next match"),
    ("Up,k", "Select previous match"),
    ("Right, l, PageDown", "Select match in next file"),
    ("Left, h, PageUp", "Select match in previous file"),
    ("gg, Home", "Jump to the first match"),
    ("Shift-g, End", "Jump to the last match"),
    ("Enter", "Open current file"),
    ("dd, Delete", "Filter out selected match"),
    ("dw", "Filter out all matches in current file"),
    ("v", "Toggle vertical context viewer"),
    ("s", "Toggle horizontal context viewer"),
    ("+", "Increase context viewer size"),
    ("-", "Decrease context viewer size"),
    ("F5, /", "Open search pattern popup"),
    ("n", "Sort search results by name"),
    ("m", "Sort search results by time modified"),
    ("c", "Sort search results by time created"),
    ("a", "Sort search results by time accessed"),
];

/// Draws the whole user interface.
pub fn draw(buffer: &mut Buffer, area: Rect, app: &mut App) {
    let status_height = 1;
    let results = Rect {
        height: area.height.saturating_sub(status_height),
        ..area
    };
    match app.context {
        ContextViewer::None => {
            render_results(buffer, results, app);
        }
        ContextViewer::Vertical => {
            let chunks = Layout::horizontal([
                Constraint::Percentage(100 - app.viewer_size),
                Constraint::Percentage(app.viewer_size),
            ])
            .split(results);
            render_results(buffer, chunks[0], app);
            render_viewer(buffer, chunks[1], app);
        }
        ContextViewer::Horizontal => {
            let chunks = Layout::vertical([
                Constraint::Percentage(100 - app.viewer_size),
                Constraint::Percentage(app.viewer_size),
            ])
            .split(results);
            render_results(buffer, chunks[0], app);
            render_viewer(buffer, chunks[1], app);
        }
    }
    render_status(buffer, Rect { y: results.bottom(), height: 1, ..area }, app);
    match app.popup.clone() {
        Popup::None => {}
        Popup::Keymap { offset_y, offset_x } => {
            render_keymap(buffer, area, app, offset_y, offset_x);
        }
        Popup::Search { value } => {
            render_search_popup(buffer, area, &value);
        }
    }
}

/// Renders the results list inside a bordered block.
fn render_results(buffer: &mut Buffer, area: Rect, app: &mut App) {
    let block = Block::bordered().border_type(BorderType::Rounded);
    let inner = block.inner(area);
    block.render(area, buffer);
    if inner.is_empty() {
        return;
    }
    let visible = inner.height as usize;
    app.scroll_results(visible);
    let selected_bg = app.theme.selected_bg;
    for (row, index) in app.items.iter().enumerate().skip(app.offset).take(visible) {
        let y = inner.y + (index - app.offset) as u16;
        let row_area = Rect {
            x: inner.x,
            y,
            width: inner.width,
            height: 1,
        };
        let selected = index == app.selected;
        if selected {
            buffer.set_style(row_area, Style::new().bg(selected_bg));
        }
        match index {
            Item::File(file) => {
                let path = display_path(&app.results[*file].path);
                let line = Line::from(Span::styled(path, Style::new().fg(Color::Indexed(13))));
                line.render(row_area, buffer);
            }
            Item::Match(file, index) => {
                let matched = &app.results[*file].matches[*index];
                let prefix = format!(" {}: ", matched.line_number);
                let mut spans = vec![Span::styled(prefix, Style::new().fg(Color::Indexed(2)))];
                let mut offset = 0usize;
                for (start, end, color) in highlight_line(
                    &app.results[*file].path,
                    &matched.text,
                    &matched.spans,
                    app,
                    selected,
                ) {
                    if start > offset {
                        spans.push(Span::raw(
                            matched.text[offset..start.min(matched.text.len())].to_string(),
                        ));
                    }
                    let end = end.min(matched.text.len());
                    spans.push(Span::styled(
                        matched.text[start.min(end)..end].to_string(),
                        Style::new().fg(color),
                    ));
                    offset = end;
                }
                if offset < matched.text.len() {
                    spans.push(Span::raw(matched.text[offset..].to_string()));
                }
                Line::from(spans).render(row_area, buffer);
            }
        }
    }
}

/// Renders the file contents of the selected match.
fn render_viewer(buffer: &mut Buffer, area: Rect, app: &mut App) {
    let block = Block::bordered().border_type(BorderType::Rounded);
    let inner = block.inner(area);
    block.render(area, buffer);
    if inner.is_empty() {
        return;
    }
    let visible = inner.height as usize;
    let Some((file, index)) = app.current_match() else {
        return;
    };
    let matched = &app.results[file].matches[index];
    let selected_line = matched.line_number as usize;
    let first = selected_line.saturating_sub(visible / 2 + 1).max(1);
    let path = app.results[file].path.clone();
    let content = read_lines(&path);
    let selected_bg = app.theme.selected_bg;
    for (row, number) in (first..).take(visible).enumerate() {
        let y = inner.y + row as u16;
        let row_area = Rect {
            x: inner.x,
            y,
            width: inner.width,
            height: 1,
        };
        let Some(text) = content.get(number - 1) else {
            continue;
        };
        if number == selected_line {
            buffer.set_style(row_area, Style::new().bg(selected_bg));
        }
        let spans: Vec<Span> = highlight_viewer(&path, text, matched, app, number == selected_line);
        Line::from(spans).render(row_area, buffer);
    }
}

/// Builds the styled spans for a line of the context viewer.
fn highlight_viewer(
    path: &std::path::Path,
    text: &str,
    matched: &crate::searcher::Match,
    app: &App,
    selected: bool,
) -> Vec<Span> {
    let theme = &app.theme;
    let mut spans = Vec::new();
    let mut ranges: Vec<(usize, usize, Color)> = Vec::new();
    let mut state = syntax::State::default();
    for token in syntax::highlight(path, text, &mut state) {
        if token.end > token.start {
            ranges.push((token.start, token.end, syntax::color(token.kind, theme)));
        }
    }
    if selected {
        for span in &matched.spans {
            ranges.retain(|(start, end, _)| !(span.start < *end && span.end > *start));
        }
    }
    for span in &matched.spans {
        ranges.push((span.start, span.end, Color::Indexed(1)));
    }
    ranges.sort_by_key(|(start, _, _)| *start);
    let mut offset = 0usize;
    for (start, end, color) in ranges {
        if start < offset {
            continue;
        }
        if start > offset {
            spans.push(Span::raw(text[offset..start.min(text.len())].to_string()));
        }
        let end = end.min(text.len());
        spans.push(Span::styled(
            text[start.min(end)..end].to_string(),
            Style::new().fg(color),
        ));
        offset = end;
    }
    if offset < text.len() {
        spans.push(Span::raw(text[offset..].to_string()));
    }
    if spans.is_empty() {
        spans.push(Span::raw(String::new()));
    }
    spans
}

/// Builds the styled spans for a match row of the results list.
fn highlight_line(
    path: &std::path::Path,
    text: &str,
    spans: &[crate::searcher::Span],
    app: &App,
    _selected: bool,
) -> Vec<(usize, usize, Color)> {
    let mut ranges: Vec<(usize, usize, Color)> = Vec::new();
    let mut state = syntax::State::default();
    for token in syntax::highlight(path, text, &mut state) {
        if token.end > token.start {
            ranges.push((token.start, token.end, syntax::color(token.kind, &app.theme)));
        }
    }
    for span in spans {
        ranges.retain(|(start, end, _)| !(span.start < *end && span.end > *start));
        ranges.push((span.start, span.end, Color::Indexed(1)));
    }
    ranges.sort_by_key(|(start, _, _)| *start);
    ranges
}

/// Reads the lines of a file, skipping invalid UTF-8.
fn read_lines(path: &std::path::Path) -> Vec<String> {
    let Ok(content) = std::fs::read(path) else {
        return Vec::new();
    };
    content
        .split(|b| *b == b'\n')
        .map(|line| String::from_utf_lossy(line).to_string())
        .collect()
}

/// Renders the bottom status line.
fn render_status(buffer: &mut Buffer, area: Rect, app: &App) {
    let total = match app.status {
        Status::Searching(found) => found,
        Status::Finished { matches, .. } => matches,
        Status::Error(_) => app.visible_matches(),
    };
    let index = app.selected_index();
    let digits = total.to_string().len().max(1);
    let counter = format!("| {:>w$}/{} ", index, total, w = digits);
    let counter_width = counter.chars().count();
    let chunks = Layout::horizontal([
        Constraint::Length(12),
        Constraint::Fill(1),
        Constraint::Length(3),
        Constraint::Length(counter_width as u16),
    ])
    .split(area);
    let (name, badge) = match &app.status {
        Status::Searching(_) => ("SEARCHING", app.theme.searching_badge()),
        Status::Finished { .. } => ("FINISHED", app.theme.finished_badge()),
        Status::Error(_) => ("ERROR", app.theme.error_badge()),
    };
    let message = match &app.status {
        Status::Searching(_) => String::new(),
        Status::Finished { matches, files, filtered } => {
            crate::app::finished_message(*matches, *files, *filtered)
        }
        Status::Error(message) => message.clone(),
    };
    let message_style = Style::new().fg(app.theme.status_fg).bg(app.theme.status_bg);
    let badge_style = Style::new().bg(badge);
    let pad = 11usize.saturating_sub(name.len());
    let left = pad / 2;
    let right = pad - left;
    let badge_line = Line::from(vec![
        Span::styled(" ".repeat(1 + left), badge_style),
        Span::styled(name.to_string(), app.theme.badge_text()),
        Span::styled(" ".repeat(right), badge_style),
    ]);
    ratatui::widgets::Paragraph::new(badge_line)
        .style(badge_style)
        .render(chunks[0], buffer);
    ratatui::widgets::Paragraph::new(message)
        .style(message_style)
        .render(chunks[1], buffer);
    let pending: String = app.pending.iter().collect();
    ratatui::widgets::Paragraph::new(pending)
        .style(message_style)
        .render(chunks[2], buffer);
    ratatui::widgets::Paragraph::new(counter)
        .style(message_style)
        .render(chunks[3], buffer);
}

/// Renders the keymap popup.
fn render_keymap(buffer: &mut Buffer, area: Rect, _app: &App, offset_y: usize, offset_x: usize) {
    let (width, height) = popup_size(area);
    let x = area.x + (area.width.saturating_sub(width)) / 2;
    let y = area.y + (area.height.saturating_sub(height)) / 2;
    let popup = Rect {
        x,
        y,
        width,
        height,
    };
    let border_style = Style::new().fg(Color::Indexed(2)).add_modifier(Modifier::BOLD);
    let block = Block::bordered()
        .border_type(BorderType::Plain)
        .border_style(border_style)
        .title_style(border_style)
        .title(Line::from(format!("igrep {VERSION}")).centered());
    block.render(popup, buffer);
    let inner = Rect {
        x: popup.x + 2,
        y: popup.y + 1,
        width: popup.width.saturating_sub(4),
        height: popup.height.saturating_sub(2),
    };
    if inner.width < 21 || inner.height < 4 {
        return;
    }
    let rows: Vec<String> = KEYMAP
        .iter()
        .map(|(keys, action)| format!("{keys:<19}│ {action}"))
        .collect();
    let separator = format!(
        "{}┼{}",
        "─".repeat(19),
        "─".repeat(inner.width as usize - 20)
    );
    let lines: Vec<String> = std::iter::once(String::new())
        .chain(std::iter::once(format!("{:<19}│ {}", "Key(s)", "Action")))
        .chain(std::iter::once(separator))
        .chain(rows)
        .collect();
    let data_height = inner.height as usize - 4;
    let data_start = inner.y + 3;
    for (row, line) in lines.iter().enumerate().skip(offset_y).take(data_height) {
        let y = data_start + (row - offset_y) as u16;
        let visible: String = line.chars().skip(offset_x).collect();
        Line::from(visible).render(
            Rect {
                x: inner.x,
                y,
                width: inner.width,
                height: 1,
            },
            buffer,
        );
    }
}

/// Renders the search pattern popup.
fn render_search_popup(buffer: &mut Buffer, area: Rect, value: &str) {
    let width = area.width / 2;
    let height = 3;
    let x = area.x + (area.width.saturating_sub(width)) / 2;
    let y = area.y + (area.height.saturating_sub(height)) / 2;
    let popup = Rect { x, y, width, height };
    let border_style = Style::new().fg(Color::Indexed(2)).add_modifier(Modifier::BOLD);
    let block = Block::bordered()
        .border_type(BorderType::Plain)
        .border_style(border_style)
        .title_style(border_style)
        .title(Line::from("Regex Pattern").centered());
    block.render(popup, buffer);
    let inner = Rect {
        x: popup.x + 1,
        y: popup.y + 1,
        width: popup.width.saturating_sub(2),
        height: 1,
    };
    Line::from(Span::styled(
        value.to_string(),
        Style::new().add_modifier(Modifier::BOLD),
    ))
    .render(inner, buffer);
}

/// Size of the keymap popup for a given screen.
fn popup_size(area: Rect) -> (u16, u16) {
    let width = ((area.width as u32 * 8 / 10) as u16).min(63);
    let height = (area.height as u32 * 8 / 10) as u16;
    (width, height)
}

/// Path as shown in the results list (the leading `./` is removed).
fn display_path(path: &std::path::Path) -> String {
    let text = path.to_string_lossy();
    text.strip_prefix("./").unwrap_or(&text).to_string()
}
