fn highlight_viewer(
    path: &std::path::Path,
    text: &str,
    matched: &crate::searcher::Match,
    app: &App,
    selected: bool,
) -> Vec<Span> {
    let theme = &app.theme;
    let mut spans = Vec::new();
    let mut ranges: Vec<(usize, usize, Color)> = Vec::new();
    let mut state = syntax::State::default();
    for token in syntax::highlight(path, text, &mut state) {
        if token.end > token.start {
            ranges.push((token.start, token.end, syntax::color(token.kind, theme)));
        }
    }
    if selected {
        for span in &matched.spans {
            ranges.retain(|(start, end, _)| !(span.start < *end && span.end > *start));
