        if start > offset {
            spans.push(Span::raw(text[offset..start.min(text.len())].to_string()));
        }
        let end = end.min(text.len());
        spans.push(Span::styled(
            text[start.min(end)..end].to_string(),
            Style::new().fg(color),
        ));
        offset = end;
