                .num_args(0..)
                .help("Files or directories to search. Directories are searched recursively. If not specified, searching starts from current directory"),
        )
        .after_help("")
}

/// Resolves the editor from the options and the environment.
fn resolve_editor(matches: &clap::ArgMatches) -> Result<EditorSpec> {
    if let Some(custom) = matches.get_one::<String>("custom_command") {
        EditorSpec::parse_custom(custom)?;
        return Ok(EditorSpec::Custom(custom.clone()));
    }
    if let Some(name) = matches.get_one::<String>("editor") {
        if let Some(spec) = EditorSpec::from_preset(name) {
            return Ok(spec);
        }
        return Ok(EditorSpec::Preset(String::new()));
    }
    for key in ["IGREP_EDITOR", "VISUAL", "EDITOR"] {
        if let Ok(name) = std::env::var(key) {
            if let Some(spec) = EditorSpec::from_preset(&name) {
                return Ok(spec);
            }
            return Ok(EditorSpec::Preset(name));
        }
    }
    Ok(EditorSpec::Preset("vim".to_string()))
}

/// Sets up the terminal, runs the event loop and restores the terminal.
fn run(mut app: App) -> Result<()> {
    let mut terminal = setup_terminal()?;
    loop {
        app.poll();
        if let Err(error) = terminal.draw(|frame| {
            ig::ui::draw(frame.buffer_mut(), frame.area(), &mut app);
        }) {
            let _ = restore_terminal(&mut terminal);
            return Err(anyhow!("{error}"));
        }
        if !handle_events(&mut app)? {
            break;
        }
        if let Some(receiver) = app.receiver.as_ref() {
            match receiver.try_recv() {
                Ok(_) | Err(TryRecvError::Disconnected) => {}
                Err(TryRecvError::Empty) => {}
            }
        }
    }
    restore_terminal(&mut terminal)?;
    Ok(())
}

/// Creates the terminal used by the user interface.
fn setup_terminal() -> Result<ratatui::DefaultTerminal> {
    crossterm::terminal::size()?;
    let backend = ig::backend::AnsiBackend::new(std::io::stdout());
    let mut terminal = ratatui::Terminal::new(backend)?;
    terminal.hide_cursor()?;
    crossterm::execute!(std::io::stdout(), crossterm::event::EnableMouseCapture)?;
    crossterm::execute!(std::io::stdout(), crossterm::terminal::EnterAlternateScreen)?;
    crossterm::execute!(std::io::stdout(), crossterm::event::DisableMouseCapture)?;
    Ok(terminal)
}

/// Restores the terminal to its original state.
fn restore_terminal(terminal: &mut ratatui::DefaultTerminal) -> Result<()> {
    crossterm::terminal::disable_raw_mode()?;
    crossterm::execute!(
        std::io::stdout(),
        crossterm::terminal::LeaveAlternateScreen,
        crossterm::cursor::Show
    )?;
    terminal.show_cursor()?;
    Ok(())
}

/// Waits for and processes all pending events.
fn handle_events(app: &mut App) -> Result<bool> {
    loop {
        if !crossterm::event::poll(Duration::from_millis(50))? {
            return Ok(true);
        }
        let event = crossterm::event::read()?;
        match event {
            crossterm::event::Event::Key(key) => {
                if key.kind != crossterm::event::KeyEventKind::Press {
                    continue;
                }
                if !handle_key(app, key) {
                    return Ok(false);
                }
            }
            crossterm::event::Event::Resize(_, _) => {}
            _ => {}
        }
    }
}

/// Handles a single key press, returning false when the app should quit.
fn handle_key(app: &mut App, key: crossterm::event::KeyEvent) -> bool {
    if key.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) {
        if let crossterm::event::KeyCode::Char('c') = key.code {
            return false;
        }
    }
    match app.popup.clone() {
        Popup::Search { value } => {
            return handle_search_key(app, key, value);
        }
        Popup::Keymap { offset_y, offset_x } => {
            return handle_keymap_key(app, key, offset_y, offset_x);
        }
        Popup::None => {}
    }
    let key_text = key_text(&key);
    if !key_text.is_empty() {
        let mut sequence: String = app.pending.iter().collect();
        sequence.push_str(&key_text);
        if let Some(action) = action_for(&sequence) {
            app.pending.clear();
            return run_action(app, action, &key);
        }
        if is_prefix(&sequence) {
            app.pending = sequence.chars().collect();
            return true;
        }
        app.pending = key_text.chars().collect();
        if let Some(action) = action_for(&key_text) {
            app.pending.clear();
            return run_action(app, action, &key);
        }
        if is_prefix(&key_text) {
            app.pending = key_text.chars().collect();
            return true;
        }
        app.pending.clear();
        return true;
    }
    match key.code {
        crossterm::event::KeyCode::Char('g') => {
            app.pending = vec!['g'];
            true
        }
        _ => true,
    }
}

/// Handles a key while the search pattern popup is open.
fn handle_search_key(app: &mut App, key: crossterm::event::KeyEvent, value: String) -> bool {
    match key.code {
        crossterm::event::KeyCode::Char(c) => {
            app.popup = Popup::Search {
                value: format!("{value}{c}"),
            };
        }
        crossterm::event::KeyCode::Backspace => {
            let mut value = value;
            value.pop();
            app.popup = Popup::Search { value };
        }
        crossterm::event::KeyCode::Enter => {
            app.popup = Popup::None;
            app.search(value);
        }
        crossterm::event::KeyCode::Esc => {
            app.popup = Popup::None;
        }
        _ => {}
    }
    true
}

/// Handles a key while the keymap popup is open.
fn handle_keymap_key(
    app: &mut App,
    key: crossterm::event::KeyEvent,
    offset_y: usize,
    offset_x: usize,
) -> bool {
    match key.code {
        crossterm::event::KeyCode::Char('?') | crossterm::event::KeyCode::F(1) => {
            app.popup = Popup::None;
        }
        crossterm::event::KeyCode::Esc => {
            app.popup = Popup::None;
        }
        crossterm::event::KeyCode::Char('q') => {
            return false;
        }
        crossterm::event::KeyCode::Down | crossterm::event::KeyCode::Char('j') => {
            app.popup = Popup::Keymap {
                offset_y: offset_y + 1,
                offset_x,
            };
        }
        crossterm::event::KeyCode::Up | crossterm::event::KeyCode::Char('k') => {
            app.popup = Popup::Keymap {
                offset_y: offset_y.saturating_sub(1),
                offset_x,
            };
        }
        crossterm::event::KeyCode::Right | crossterm::event::KeyCode::Char('l') => {
            app.popup = Popup::Keymap {
                offset_y,
                offset_x: offset_x + 1,
            };
        }
        crossterm::event::KeyCode::Left | crossterm::event::KeyCode::Char('h') => {
            app.popup = Popup::Keymap {
                offset_y,
                offset_x: offset_x.saturating_sub(1),
            };
        }
        _ => {
            app.popup = Popup::None;
        }
    }
    true
}

/// Key sequence for a key event, as used by the key bindings.
fn key_text(key: &crossterm::event::KeyEvent) -> String {
    use crossterm::event::KeyCode;
    match key.code {
        KeyCode::Char(c) => c.to_string(),
        KeyCode::Delete => "Delete".to_string(),
        KeyCode::Home => "Home".to_string(),
        KeyCode::End => "End".to_string(),
        KeyCode::PageUp => "PageUp".to_string(),
        KeyCode::PageDown => "PageDown".to_string(),
        KeyCode::Enter => "Enter".to_string(),
        KeyCode::F(5) => "F5".to_string(),
        _ => String::new(),
    }
}

/// Whether `sequence` is a prefix of one of the multi key bindings.
fn is_prefix(sequence: &str) -> bool {
    sequence == "d" || sequence == "g"
}

/// Action bound to a key sequence.
#[derive(Clone, Copy, Eq, PartialEq)]
enum Action {
    NextMatch,
    PreviousMatch,
    NextFile,
    PreviousFile,
    FirstMatch,
    LastMatch,
    Open,
    FilterSelected,
    FilterFile,
    VerticalViewer,
    HorizontalViewer,
    IncreaseViewer,
    DecreaseViewer,
    SearchPopup,
    KeymapPopup,
    SortPath,
    SortModified,
    SortCreated,
    SortAccessed,
    DeleteKey,
    Quit,
}

/// Resolves a key sequence to an action.
fn action_for(sequence: &str) -> Option<Action> {
    use crossterm::event::KeyCode;
    let _ = KeyCode::Null;
    Some(match sequence {
        "j" => Action::NextMatch,
        "k" => Action::PreviousMatch,
        "l" => Action::NextFile,
        "h" => Action::PreviousFile,
        "gg" => Action::FirstMatch,
        "G" => Action::LastMatch,
        "dd" => Action::FilterSelected,
        "dw" => Action::FilterFile,
        "v" => Action::VerticalViewer,
        "s" => Action::HorizontalViewer,
        "+" => Action::IncreaseViewer,
        "-" => Action::DecreaseViewer,
        "F5" | "/" => Action::SearchPopup,
        "?" | "F1" => Action::KeymapPopup,
        "n" => Action::SortPath,
        "m" => Action::SortModified,
        "c" => Action::SortCreated,
        "a" => Action::SortAccessed,
        "Enter" => Action::Open,
        "Delete" => Action::DeleteKey,
        "q" => Action::Quit,
        _ => return None,
    })
}

/// Runs an action.
fn run_action(app: &mut App, action: Action, key: &crossterm::event::KeyEvent) -> bool {
    use crossterm::event::KeyCode;
    match action {
        Action::Quit => return false,
        Action::NextMatch => app.next_match(),
        Action::PreviousMatch => app.previous_match(),
        Action::NextFile => app.next_file(),
        Action::PreviousFile => app.previous_file(),
        Action::FirstMatch => app.first_match(),
        Action::LastMatch => app.last_match(),
        Action::Open => {
            if let Err(error) = ig::editor::open(app) {
                app.status = Status::Error(error);
            }
        }
        Action::FilterSelected => app.filter_selected(),
        Action::FilterFile => app.filter_file(),
        Action::VerticalViewer => {
            app.context = if app.context == ContextViewer::Vertical {
                ContextViewer::None
            } else {
                ContextViewer::Vertical
            };
        }
        Action::HorizontalViewer => {
            app.context = if app.context == ContextViewer::Horizontal {
                ContextViewer::None
            } else {
                ContextViewer::Horizontal
            };
        }
        Action::IncreaseViewer => {
            app.viewer_size = (app.viewer_size + 5).min(80);
        }
        Action::DecreaseViewer => {
            app.viewer_size = app.viewer_size.saturating_sub(5).max(20);
        }
        Action::SearchPopup => {
            app.popup = Popup::Search {
                value: app.pattern.clone(),
            };
        }
        Action::KeymapPopup => {
            app.popup = Popup::Keymap {
                offset_y: 0,
                offset_x: 0,
            };
        }
        Action::SortPath => app.sort_by(SortBy::Path, false),
        Action::SortModified => app.sort_by(SortBy::Modified, false),
        Action::SortCreated => app.sort_by(SortBy::Created, false),
        Action::SortAccessed => app.sort_by(SortBy::Accessed, false),
        Action::DeleteKey => app.filter_selected(),
    }
    let _ = key;
    let _ = KeyCode::Null;
    true
}
RSEOF
